-- Remember which identities are missing before inserting any songs.
CREATE TEMPORARY TABLE mrs_seed_new_song LIKE song;
INSERT INTO mrs_seed_new_song
SELECT seed.*
FROM mrs_seed_song seed
LEFT JOIN song existing
    ON existing.source_provider = seed.source_provider
    AND existing.external_source_id = seed.external_source_id
WHERE existing.id IS NULL;

-- Keep the complete vocabulary, including tags not currently attached to songs.
-- Reuse tag IDs already present, including case-insensitive name matches.
INSERT INTO tag (type, name)
SELECT seed_tag.type, seed_tag.name
FROM mrs_seed_tag seed_tag
LEFT JOIN tag existing ON existing.type = seed_tag.type AND existing.name = seed_tag.name
WHERE existing.id IS NULL;

INSERT INTO song (title, artist, duration, source_provider, external_source_id,
    audio_url, cover_url, ambience_a, ambience_b, ambience_source_url,
    bpm, is_explicit, isrc, source_etag, version)
SELECT title, artist, duration, source_provider, external_source_id,
    audio_url, cover_url, ambience_a, ambience_b, ambience_source_url,
    bpm, is_explicit, isrc, source_etag, 0
FROM mrs_seed_new_song
ORDER BY id;

-- Resolve both sides using natural keys, never the snapshot's numeric IDs.
INSERT INTO song_tag (song_id, tag_id)
SELECT actual_song.id, actual_tag.id
FROM mrs_seed_song_tag link
JOIN mrs_seed_new_song seed_song ON seed_song.id = link.song_id
JOIN song actual_song ON actual_song.source_provider = seed_song.source_provider
    AND actual_song.external_source_id = seed_song.external_source_id
JOIN mrs_seed_tag seed_tag ON seed_tag.id = link.tag_id
JOIN tag actual_tag ON actual_tag.type = seed_tag.type AND actual_tag.name = seed_tag.name;

DROP TEMPORARY TABLE mrs_seed_new_song;
DROP TEMPORARY TABLE mrs_seed_song_tag;
DROP TEMPORARY TABLE mrs_seed_tag;
DROP TEMPORARY TABLE mrs_seed_song;
SET SESSION sql_mode = @mrs_seed_sql_mode;
